#include <vector>
#include <string>

class Robot {
private:
    int w, h, perimeter, pos;
    bool moved;

public:
    Robot(int width, int height) : w(width), h(height), perimeter(2 * (width + height) - 4), pos(0), moved(false) {}

    void step(int num) {
        moved = true;
        pos = (pos + num) % perimeter;
    }

    std::vector<int> getPos() {
        int p = pos;
        if (p < w) return {p, 0};
        p -= (w - 1);
        if (p < h) return {w - 1, p};
        p -= (h - 1);
        if (p < w) return {w - 1 - p, h - 1};
        p -= (w - 1);
        return {0, h - 1 - p};
    }

    std::string getDir() {
        if (!moved) return "East";
        int p = pos;
        if (p == 0) return "South";
        if (p < w) return "East";
        p -= (w - 1);
        if (p < h) return "North";
        p -= (h - 1);
        if (p < w) return "West";
        return "South";
    }
};

class Robot {
    private int w, h, perimeter, pos;
    private boolean moved;

    public Robot(int width, int height) {
        this.w = width;
        this.h = height;
        this.perimeter = 2 * (width + height) - 4;
        this.pos = 0;
        this.moved = false;
    }

    public void step(int num) {
        moved = true;
        pos = (pos + num) % perimeter;
    }

    public int[] getPos() {
        int p = pos;
        if (p < w) return new int[]{p, 0};
        p -= (w - 1);
        if (p < h) return new int[]{w - 1, p};
        p -= (h - 1);
        if (p < w) return new int[]{w - 1 - p, h - 1};
        p -= (w - 1);
        return new int[]{0, h - 1 - p};
    }

    public String getDir() {
        if (!moved) return "East";
        int p = pos;
        if (p == 0) return "South";
        if (p < w) return "East";
        p -= (w - 1);
        if (p < h) return "North";
        p -= (h - 1);
        if (p < w) return "West";
        return "South";
    }
}

/**
 * @param {number} width
