 */
var Robot = function(width, height) {
    this.w = width;
    this.h = height;
    this.perimeter = 2 * (width + height) - 4;
    this.pos = 0;
    this.moved = false;
};

Robot.prototype.step = function(num) {
    this.moved = true;
    this.pos = (this.pos + num) % this.perimeter;
};

Robot.prototype.getPos = function() {
    let p = this.pos;
    const { w, h } = this;
    if (p < w) return [p, 0];
    p -= (w - 1);
    if (p < h) return [w - 1, p];
    p -= (h - 1);
    if (p < w) return [w - 1 - p, h - 1];
    p -= (w - 1);
    return [0, h - 1 - p];
};

Robot.prototype.getDir = function() {
    if (!this.moved) return "East";
    let p = this.pos;
    const { w, h } = this;
    if (p === 0) return "South";
    if (p < w) return "East";
    p -= (w - 1);
    if (p < h) return "North";
    p -= (h - 1);
    if (p < w) return "West";
    return "South";
};
